import{_ as s,c as a,o as e,b0 as i}from"./chunks/framework.Becqh7-x.js";const n="/linux-dev-docs/assets/image-20241002075835226.9ZThUOJQ.png",d="/linux-dev-docs/assets/image-20241002075859486.CUWZJ-Hf.png",p="/linux-dev-docs/assets/image-20241002080311946.BlMN_ccc.png",l="/linux-dev-docs/assets/image-20241002080638895.BkkJiOCF.png",r="/linux-dev-docs/assets/image-20241002080754732.Cr0OtwQv.png",b="/linux-dev-docs/assets/image-20241002080958549.Dj-wr6gg.png",h="/linux-dev-docs/assets/image-20241002081100031.C483xWN6.png",o="/linux-dev-docs/assets/image-20241002081118062.CJHakreS.png",c="/linux-dev-docs/assets/image-20241002081141751.CCjOUOSk.png",m="/linux-dev-docs/assets/image-20241002084850923.FSWjh1HA.png",x=JSON.parse('{"title":"LV060-显示BMP图片","description":null,"frontmatter":{"title":"LV060-显示BMP图片","date":"2026-01-07T16:17:21.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/application/lcd/126d2c7d90793029acad4b73","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-07T16:17:21.770Z","fulluuid":"9acad4b737574d2cb6b41e8edb995bed","useduuid":"9acad4b73"}},"headers":[],"relativePath":"sdoc/application/lcd/126d2c7d90793029acad4b73.md","filePath":"sdoc/20-应用开发/20-LCD应用/LV060-显示BMP图片.md","lastUpdated":1768604092000}'),g={name:"sdoc/application/lcd/126d2c7d90793029acad4b73.md"};function u(k,t,E,B,P,y){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="lv060-显示bmp图片" tabindex="-1">LV060-显示BMP图片 <a class="header-anchor" href="#lv060-显示bmp图片" aria-label="Permalink to &quot;LV060-显示BMP图片&quot;">​</a></h1><h2 id="一、bmp-图片格式" tabindex="-1">一、BMP 图片格式 <a class="header-anchor" href="#一、bmp-图片格式" aria-label="Permalink to &quot;一、BMP 图片格式&quot;">​</a></h2><blockquote><p>这个可以直接看《<a href="https://docs-site.github.io/media-docs/sdoc/image/img-file-format/126b08d824b52a429241be3f.html" target="_blank" rel="noreferrer">LV015-BMP 文件格式 | Media</a>》这篇笔记，这篇笔记详细学习了 BMP 文件格式。不过这里还是简单的再了解一下。</p></blockquote><h3 id="_1-bmp-图像介绍" tabindex="-1">1. BMP 图像介绍 <a class="header-anchor" href="#_1-bmp-图像介绍" aria-label="Permalink to &quot;1. BMP 图像介绍&quot;">​</a></h3><p>我们常用的图片格式有很多，一般最常用的有三种： JPEG（或 JPG）、 PNG、 BMP 和 GIF。其中 JPEG（或 JPG）、 PNG 以及 BMP 都是静态图片，而 GIF 则可以实现动态图片。</p><p>BMP（全称 Bitmap）是 Window 操作系统中的标准图像文件格式，文件后缀名为“.bmp”，使用非常广。它采用位映射存储格式，除了图像深度可选以外，图像数据没有进行任何压缩，因此， BMP 图像文件所占用的空间很大，但是没有失真、 并且解析 BMP 图像简单。</p><p>BMP 文件的图像深度可选 lbit、 4bit、 8bit、 16bit、 24bit 以及 32bit， 典型的 BMP 图像文件由四部分组成：</p><p>①、 BMP 文件头（BMP file header），它包含 BMP 文件的格式、大小、 位图数据的偏移量等信息；</p><p>②、位图信息头（bitmap information） ，它包含位图信息头大小、 图像的尺寸、 图像大小、 位平面数、压缩方式以及颜色索引等信息；</p><p>③、调色板（color palette），这部分是可选的，如果使用索引来表示图像， 调色板就是索引与其对应颜色的映射表；</p><p>④、位图数据（bitmap data），也就是图像数据。</p><p>BMP 文件头、位图信息头、调色板和位图数据， 总结如下表所示：</p><table tabindex="0"><thead><tr><th style="text-align:center;">数据段名称</th><th style="text-align:center;">大小（Byte）</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">bmp 文件头 (bmp file header)</td><td style="text-align:center;">14</td><td>包含 BMP 文件的格式、大小、到位图数据的 偏移量等信息</td></tr><tr><td style="text-align:center;">位图信息头 (bitmap information）</td><td style="text-align:center;">通常为 40 或 56 字节</td><td>包含位图信息头大小、 图像的尺寸、图像大 小、位平面数、 压缩方式以及颜色索引等信 息；</td></tr><tr><td style="text-align:center;">调色板 (color palette)</td><td style="text-align:center;">由颜色索引数决定</td><td>可选，如果使用索引来表示图像的颜色， 则调 色板就是索引与其对应颜色的映射表；</td></tr><tr><td style="text-align:center;">位图数据 (bitmap data）</td><td style="text-align:center;">由图像尺寸决定</td><td>图像数据</td></tr></tbody></table><p>一般常见的图像都是以 16 位（R、 G、 B 三种颜色分别使用 5bit、 6bit、 5bit 来表示）、 24 位（R、 G、B 三种颜色都使用 8bit 来表示） 色图像为主，我们称这样的图像为真彩色图像， 真彩色图像是不需要调色板的，即位图信息头后面紧跟的就是位图数据了。</p><p>对某些 BMP 位图文件说并非如此， 如 16 色位图、 256 色位图，它们需要使用到调色板，具体调色板如何使用，我们不关心，这里我们将会以 16 位色（RGB565） BMP 图像为例进行学习。</p><h3 id="_2-bmp-图像格式" tabindex="-1">2. BMP 图像格式 <a class="header-anchor" href="#_2-bmp-图像格式" aria-label="Permalink to &quot;2. BMP 图像格式&quot;">​</a></h3><p>以一张 16 位 BMP 图像为例（这张图在迁移笔记的时候找不到了，不过可以看<a href="https://docs-site.github.io/media-docs/sdoc/image/img-file-format/126b08d824b52a429241be3f.html" target="_blank" rel="noreferrer">LV015-BMP 文件格式 | Media</a>，这里分析的更详细一些），首先在 Windows 下查看该图片的属性，如下所示：</p><img src="'+n+'" alt="image-20241002075835226"><p>可以看到该图片的分辨率为 800*480，位深度为 16bit，每个像素点使用 16 位表示，也就是 RGB565。接下来使用十六进制查看工具将 image.bmp 文件打开，文件头部分的内容如下所示：</p><img src="'+d+`" alt="image-20241002075859486"><h4 id="_1-bmp-文件头" tabindex="-1">1. bmp 文件头 <a class="header-anchor" href="#_1-bmp-文件头" aria-label="Permalink to &quot;1. bmp 文件头&quot;">​</a></h4><p>Windows 下为 bmp 文件头定义了如下结构体：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tagBITMAPFILEHEADER</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UINT16 bfType;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD bfSize;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UINT16 bfReserved1;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UINT16 bfReserved2;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD bfOffBits;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} BITMAPFILEHEADER;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>结构体中每一个成员说明如下：</p><table tabindex="0"><thead><tr><th>变量名</th><th>地址偏移</th><th>大小</th><th>作用</th></tr></thead><tbody><tr><td>bfType</td><td>00H</td><td>2 bytes</td><td>说明 bmp 文件的类型，可取值为： ①BM – Windows ②BA – OS/2 Bitmap Array ③CI – OS/2 Color Icon④CP – OS/2 Color Pointer ⑤IC – OS/2 Icon ⑥PT – OS/2 Pointer</td></tr><tr><td>bfSize</td><td>02H</td><td>4 bytes</td><td>说明该文件的大小，以字节为单位。</td></tr><tr><td>bfReserved1</td><td>06H</td><td>2 bytes</td><td>保留字段，必须设置为 0。</td></tr><tr><td>bfReserved2</td><td>08H</td><td>2 bytes</td><td>保留字段，必须设置为 0。</td></tr><tr><td>bfOffBits</td><td>0AH</td><td>4 bytes</td><td>说明从文件起始位置到图像数据之间的字节偏移量。 这个参数非常有用，因为位图信息头和调色板的长度 会根据不同的情况而变化，所以我们可以用这个偏移 量迅速从文件中找到图像数据的偏移地址。</td></tr></tbody></table><p>bmp 文件头的大小固定为 14 个字节。 从上面的描述信息，再来对照文件数据：</p><img src="`+p+`" alt="image-20241002080311946"><p>00~01H： 0x42、 0x4D 对应的 ASCII 字符分别为为 B、 M，表示这是 Windows 所支持的位图格式，该字段必须是“BM”才是 Windows 位图文件。</p><p>02~05H： 对应于文件大小， 0x000BB848 = 768072 字节，与 image.bmp 文件大小是相符的。</p><p>06~09H： 保留字段。</p><p>0A~0D： 0x00000046 = 70，即从文件头部开始到位图数据需要偏移 70 个字节。</p><h4 id="_1-2-位图信息头" tabindex="-1">1.2 位图信息头 <a class="header-anchor" href="#_1-2-位图信息头" aria-label="Permalink to &quot;1.2 位图信息头&quot;">​</a></h4><p>同样， Windows 下为位图信息头定义了如下结构体：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tagBITMAPINFOHEADER {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD biSize;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LONG biWidth;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LONG biHeight;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WORD biPlanes;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WORD biBitCount;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD biCompression;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD biSizeImage;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LONG biXPelsPerMeter;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LONG biYPelsPerMeter;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD biClrUsed;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DWORD biClrImportant;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} BITMAPINFOHEADER;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>结构体中每一个成员说明如下 :</p><table tabindex="0"><thead><tr><th>变量名</th><th>地址偏移</th><th>大小</th><th>作用</th></tr></thead><tbody><tr><td>biSize</td><td>0EH</td><td>4 bytes</td><td>位图信息头大小。</td></tr><tr><td>biWidth</td><td>12H</td><td>4 bytes</td><td>图像的宽度，以像素为单位。</td></tr><tr><td>biHeight</td><td>16H</td><td>4 bytes</td><td>图像的高度，以像素为单位。 注意，这个值除了用于描述图像的高度之外， 它还有另外一个用途，用于指明该图像是倒向 的位图、还是正向的位图。 如果该值是一个正数，说明是倒向的位图；如果该值是一个负数，则说明是正向的位图。 一般情况下， BMP 图像都是倒向的位图，也就是该值是一个正数。</td></tr><tr><td>biPlanes</td><td>1AH</td><td>2 bytes</td><td>色彩平面数，该值总被设置为 1。</td></tr><tr><td>biBitCount</td><td>1CH</td><td>2 bytes</td><td>像素深度，指明一个像素点需要多少个 bit 数据 来描述，其值可为 1、 4、 8、 16、 24、 32</td></tr><tr><td>biCompression</td><td>1EH</td><td>4 bytes</td><td>说明图像数据的压缩类型，取值范围如下： ①0 – RGB 方式 ②1 – 8bpp 的 RLE 方式，只用于 8bit 位图 ③2 – 4bpp 的 RLE 方式， 只用于 4bit 位图 ④3 – Bit-fields 方式 ⑤4 – 仅用于打印机 ⑥5 – 仅用于打印机</td></tr><tr><td>biSizeImage</td><td>22H</td><td>4 bytes</td><td>说明图像的大小，以字节为单位，当压缩类型 为 BI_RGB 时，可设置为 0。</td></tr><tr><td>biXPelsPerMeter</td><td>26H</td><td>4 bytes</td><td>水平分辨率，用像素/米来表示，有符号整数。</td></tr><tr><td>biYPelsPerMeter</td><td>2AH</td><td>4 bytes</td><td>垂直分辨率，用像素/米来表示，有符号整数。</td></tr><tr><td>biClrUsed</td><td>2EH</td><td>4 bytes</td><td>说明位图实际使用的彩色表中的颜色索引数。</td></tr><tr><td>biClrImportant</td><td>32H</td><td>4 bytes</td><td>说明对图像显示有重要影响的颜色索引的数 目，如果是 0，则表示都重要。</td></tr></tbody></table><p>从上面的描述信息，再来对照文件数据：</p><img src="`+l+'" alt="image-20241002080638895"><p>0E~11H： 0x00000038 = 56，这说明这个位图信息头的大小为 56 个字节。</p><p>12~15H： 0x00000320 = 800，图像宽度为 800 个像素，与文件属性一致。</p><p>16~19H： 0x000001E0 = 480，图像高度为 480 个像素，与文件属性一致；这个数是一个正数，说明是一个倒向的位图，什么是正向的位图、什么是倒向的位图， 说的是图像数据的排列问题； 如果是正向的位图， 图像数据是按照图像的左上角到右下角方式排列的，水平方向从左到右，垂直方向从上到下。倒向的位图，图像数据则是按照图像的左下角到右上角方式排列的，水平方向依然从左到右，垂直方向改为从下到上。</p><p>1A~1BH： 0x0001 = 1，这个值总为 1。</p><p>1C~1DH： 0x0010 = 16，表示每个像素占 16 个 bit。</p><p>1E~21H： 0x00000003 = 3， bit-fileds 方式。</p><p>22~25H： 0x000BB802 = 768002，图像的大小，注意图像的大小并不是 BMP 文件的大小，而是图像数据的大小。</p><p>26~29H： 0x00000EC2 = 3778，水平分辨率为 3778 像素/米。</p><p>2A~2DH： 0x00000EC2 = 3778，垂直分辨率为 3778 像素/米。</p><p>2E~31H： 0x00000000 = 0，本位图未使用调色板。</p><p>32~35H： 0x00000000 = 0。</p><p>只有压缩方式选项被设置为 bit-fileds（0x3） 时， 位图信息头的大小才会等于 56 字节，否则，为 40 字节。 56 个字节相比于 40 个字节，多出了 16 个字节， 那么多出的 16 个字节数据描述了什么信息呢？ 稍后再学习。</p><h4 id="_1-3-调色板" tabindex="-1">1.3 调色板 <a class="header-anchor" href="#_1-3-调色板" aria-label="Permalink to &quot;1.3 调色板&quot;">​</a></h4><p>调色板是单色、 16 色、 256 色位图图像文件所持有的，如果是 16 位、 24 位以及 32 位位图文件，则 BMP 文件组成部分中不包含调色板，这里就不深入了解了。</p><h4 id="_1-4-位图数据" tabindex="-1">1.4 位图数据 <a class="header-anchor" href="#_1-4-位图数据" aria-label="Permalink to &quot;1.4 位图数据&quot;">​</a></h4><p>位图数据其实就是图像的数据， 对于 24 位位图，使用 3 个字节数据来表示一个像素点的颜色，对于 16 位位图，使用 2 个字节数据来表示一个像素点的颜色，同理， 32 位位图则使用 4 个字节来描述。BMP 位图分为正向的位图和倒向的位图，主要区别在于图像数据存储的排列方式， 如下如所示（左边对应的是正向位图，右边对应的则是倒向位图） ：</p><img src="'+r+'" alt="image-20241002080754732"><p>所以正向位图先存储图像的第一行数据，从左到右依次存放，接着存放第二行，依次这样；而倒向位图，则先存储图像的最后一行（倒数第一行）数据，也是从左到右依次存放，接着倒数二行，依次这样。</p><h2 id="二、rgb-和-bit-fields" tabindex="-1">二、RGB 和 Bit-Fields <a class="header-anchor" href="#二、rgb-和-bit-fields" aria-label="Permalink to &quot;二、RGB 和 Bit-Fields&quot;">​</a></h2><p>当图像中引用的色彩超过 256 种时，就需要 16bpp 或更高 bpp 的位图（24 位、 32 位）。调色板不适合 bpp 较大的位图，因此 16bpp 及以上的位图都不使用调色板，不使用调色板的位图图像有两种编码格式：RGB 和 Bit-Fields（下称 BF） 。</p><p>RGB 编码格式是一种均分的思想， 使 Red、 Green、 Blue 三种颜色信息容量一样大，譬如 24bpp-RGB，它通常只有这一种编码格式，在 24bits 中，低 8 位表示 Blue 分量；中 8 为表示 Green 分量；高 8 位表示 Red 分量。</p><p>而在 32bpp-RGB 中，低 24 位的编码方式与 24bpp 位图相同，最高 8 位用来表示透明度 Alpha 分量。32bpp 的位图尺寸太大，一般只有在图像处理的中间过程中使用。对于需要半透过效果的图像，更好的选择是 PNG 格式。</p><p>BF 编码格式与 RGB 不同，它利用位域操作，人为地确定 RGB 三分量所包含的信息容量。 位图信息头介绍中提及到，当压缩方式选项置为 BF 时， 位图信息头大小比平时多出 16 字节， 这 16 个字节实际上是 4 个 32bit 的位域掩码， 按照先后顺序，它们分别是 R、 G、 B、 A 四个分量的位域掩码， 当然如果没有 Alpha 分量，则 Alpha 掩码没有实际意义。</p><p>位域掩码的作用是指出 R、 G、 B 三种颜色信息容量的大小，分别使用多少个 bit 数据来表示，以及三种颜色分量的位置偏移量。例如对于 16 位色的 RGB565 图像，通常使用 BF 编码格式，同样这也是 BF 编码格式最著名和最普遍的应用之一， 它的 R、 G 和 B 分量的位域掩码分别是 0xF800、 0x07E0 和 0x001F，也就是 R 通道使用 2 个字节中的高 5 位表示， G 通道使用 2 个字节中的中间 6 位表示。而 B 通道则使用 2 个字节中的最低 5 位表示， 如下图所示：</p><img src="'+b+'" alt="image-20241002080958549"><h2 id="三、如何得到-16-位色-rgb565-格式-bmp-图像" tabindex="-1">三、如何得到 16 位色 RGB565 格式 BMP 图像？ <a class="header-anchor" href="#三、如何得到-16-位色-rgb565-格式-bmp-图像" aria-label="Permalink to &quot;三、如何得到 16 位色 RGB565 格式 BMP 图像？&quot;">​</a></h2><p>在 Windows 下我们转换得到的 BMP 位图通常是 24 位色的 RGB888 格式图像，那如何得到 RGB565 格式 BMP 位图呢？当然这个方法很多，这里可以通过 Photoshop 软件来得到 RGB565 格式的 BMP 位图。</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+h+'" style="width:50%;height:auto;" alt="img"></td><td align="center" style="border:none;"><img src="'+o+'" style="width:100%;height:auto;" alt="img"></td><td align="center" style="border:none;"><img src="'+c+'" style="width:100%;height:auto;" alt="img"></td></tr></tbody></table><p>首先，找一张图片，图片格式无所谓，只要 Photoshop 软件能打开即可；确定图片之后，我们启动 Photoshop 软件，并且使用 Photoshop 软件打开这张图片， 打开之后点击菜单栏中的【文件】→ 【存储为】，接着出现上图最左侧的界面：</p><p>在这个界面中，首先选择文件保存的路径，然后设置文件名以及文件格式，选择文件格式为 BMP 格式，之后点击保存，如上面中间的图片所示。然后点击选择 16 位色图，接着点击高级模式按钮，再点击选择 RGB565，接着点击确定按钮即可，这样就可得到 16 位色 RGB565 格式的 BMP 图像。</p><h2 id="四、lcd-显示-bmp-图像实例" tabindex="-1">四、LCD 显示 BMP 图像实例 <a class="header-anchor" href="#四、lcd-显示-bmp-图像实例" aria-label="Permalink to &quot;四、LCD 显示 BMP 图像实例&quot;">​</a></h2><h3 id="_1-代码编写" tabindex="-1">1. 代码编写 <a class="header-anchor" href="#_1-代码编写" aria-label="Permalink to &quot;1. 代码编写&quot;">​</a></h3><p>代码及 Makefile 可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-app-demo/tree/master/LV18_LCD_DEVICE/03_lcd_show_bmp" target="_blank" rel="noreferrer">LV18_LCD_DEVICE/03_lcd_show_bmp · linux-dev-org/imx6ull-app-demo</a></p><h3 id="_2-开发板测试" tabindex="-1">2. 开发板测试 <a class="header-anchor" href="#_2-开发板测试" aria-label="Permalink to &quot;2. 开发板测试&quot;">​</a></h3><p>直接在终端执行以下命令即可：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./app_demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image.bmp</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><img src="'+m+'" alt="image-20241002084850923">',75)])])}const f=s(g,[["render",u]]);export{x as __pageData,f as default};
